def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Border runs define rays perpendicular to that border. Each interior
    # marker extends toward the nearest border run that it is aligned with.
    runs = []
    for side in ("top", "bottom", "left", "right"):
        if side in ("top", "bottom"):
            r = 0 if side == "top" else h - 1
            c = 0
            while c < w:
                color = grid[r][c]
                if color == bg:
                    c += 1
                    continue
                end = c
                while end + 1 < w and grid[r][end + 1] == color:
                    end += 1
                if end > c:
                    runs.append((side, c, end))
                c = end + 1
        else:
            c = 0 if side == "left" else w - 1
            r = 0
            while r < h:
                color = grid[r][c]
                if color == bg:
                    r += 1
                    continue
                end = r
                while end + 1 < h and grid[end + 1][c] == color:
                    end += 1
                if end > r:
                    runs.append((side, r, end))
                r = end + 1

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            candidates = []
            for side, a, b in runs:
                if side in ("top", "bottom") and a <= c <= b:
                    candidates.append(side)
                if side in ("left", "right") and a <= r <= b:
                    candidates.append(side)
            if not candidates:
                continue
            side = min(candidates, key=lambda s: {
                "top": r, "bottom": h - 1 - r,
                "left": c, "right": w - 1 - c
            }[s])
            out[r][c] = 4
            dr, dc = {"top": (-1, 0), "bottom": (1, 0),
                      "left": (0, -1), "right": (0, 1)}[side]
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out
